function bounds(vals){let lo=Infinity,hi=-Infinity;for(const v of vals){if(v<lo)lo=v;if(v>hi)hi=v;}if(!Number.isFinite(lo))return [0,1];const pad=(hi-lo)*.12||Math.abs(hi)*.08||1;return [lo-pad,hi+pad]}
