function timeline(){const {c,w,h,el}=canvas('timeline'),L=65,R=70,T=23,B=45,pw=w-L-R,ph=h-T-B;const {a,b,nm,rm}=view;let list=[{name:view.node,data:view.series,color:palette[0]}];if($('compare').checked)list=Object.keys(D.nodes).map((name,i)=>({name,color:palette[i],data:aggregate(D.nodes[name].filter(r=>r[0]>a&&r[0]<=b),nm,'node')}));const all=list.flatMap(s=>s.data.filter(p=>p.v!=null).map(p=>p.v));const [lo,hi]=bounds(all),[rl,rh]=bounds(view.regional.filter(p=>p.v!=null).map(p=>p.v));const x=t=>L+(t-a)/(b-a)*pw,y=v=>T+(hi-v)/(hi-lo)*ph,ry=v=>T+(rh-v)/(rh-rl)*ph;c.textAlign='right';for(let i=0;i<=4;i++){const yy=T+i*ph/4;c.strokeStyle=chartColor('#e8ecf2');c.beginPath();c.moveTo(L,yy);c.lineTo(w-R,yy);c.stroke();c.fillStyle=chartColor('#43516a');c.fillText(compact(hi-(hi-lo)*i/4),L-10,yy+4);if(rm!=='none'){c.fillStyle=chartColor('#43516a');c.textAlign='left';c.fillText(compact(rh-(rh-rl)*i/4),w-R+10,yy+4);c.textAlign='right'}}c.textAlign='left';c.fillStyle=chartColor('#b9650d');c.fillText(unit(nm),L,12);if(rm!=='none'){c.fillStyle=chartColor('#43516a');c.textAlign='right';c.fillText('MW',w-R,12)}for(let i=0;i<=5;i++){const t=a+(b-a)*i/5;c.textAlign=i===0?'left':i===5?'right':'center';c.fillStyle=chartColor('#43516a');const fmt=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Manila',...(b-a<=86400000?{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}:{day:'2-digit',month:'short'})});c.fillText(fmt.format(t),x(t),h-14)}const step=resolution==='5m'?300000:resolution==='hour'?3600000:86400000;
function draw(points,color,Y,dashed=false){c.strokeStyle=chartColor(color);c.lineWidth=dashed?1.7:2;c.setLineDash(dashed?[5,4]:[]);c.beginPath();let prev=null; // At long ranges retain extrema per screen column, rather than smoothing away spikes.
let ps=points.map((p,i)=>({...p,breakBefore:i>0&&p.t-points[i-1].t>step*1.5}));if(ps.length>pw*3){const buckets=new Map();for(const p of ps){const k=Math.floor(x(p.t));if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(p)}ps=[];for(const bucket of buckets.values()){let min=bucket[0],max=bucket[0];for(const p of bucket){if(p.v<min.v)min=p;if(p.v>max.v)max=p}ps.push(...[bucket[0],min,max,bucket.at(-1),...bucket.filter(p=>p.breakBefore)].filter((p,i,arr)=>arr.indexOf(p)===i).sort((u,v)=>u.t-v.t))}}
for(const p of ps){if(p.v==null){prev=null;continue}if(!prev||p.breakBefore)c.moveTo(x(p.t),Y(p.v));else c.lineTo(x(p.t),Y(p.v));prev=p}c.stroke();c.setLineDash([])}
if(rm!=='none')draw(view.regional,'#16476b',ry,true);for(const s of list)draw(s.data,s.color,y);if(!all.length){c.textAlign='center';c.fillStyle=chartColor('#43516a');c.fillText('No observations in this window',w/2,h/2)}
view.chart={L,R,T,B,pw,ph,x,y,lo,hi,w,h,list};el.onmousemove=e=>{const box=el.getBoundingClientRect(),xx=e.clientX-box.left,tt=a+(xx-L)/pw*(b-a);const data=view.series;if(!data.length||xx<L||xx>w-R){$('tooltip').style.display='none';return}let low=0,high=data.length-1;while(low<high){const mid=(low+high)>>1;if(data[mid].t<tt)low=mid+1;else high=mid}let p=data[low];if(low>0&&Math.abs(data[low-1].t-tt)<Math.abs(p.t-tt))p=data[low-1];const reg=view.regional.find(q=>q.t===p.t);const tip=$('tooltip');tip.innerHTML='<b>'+stamp(p.t)+'</b><br>'+view.node+'<br>'+labels[nm]+': '+num(p.v)+' '+unit(nm)+(reg?'<br>Visayas '+labels[rm]+': '+num(reg.v)+' MW':'')+'<br><span style="color:#a9c5d6">'+p.n+' node observations in bin</span>';tip.style.display='block';tip.style.left=Math.max(0,Math.min(w-260,xx+12))+'px';tip.style.top='35px'};el.onmouseleave=()=>$('tooltip').style.display='none'}
function profile(){const {c,w,h}=canvas('profile'),groups=Array.from({length:24},()=>[]);for(const row of view.nodes){const hour=new Date(row[0]-1+28800000).getUTCHours();groups[hour].push(val(row,'LMP','node'))}const vals=groups.map(mean),[lo,hi]=bounds(vals.filter(x=>x!=null)),L=51,R=14,T=18,B=30,pw=w-L-R,ph=h-T-B;for(let i=0;i<=3;i++){const yy=T+i*ph/3;c.strokeStyle=chartColor('#e8ecf2');c.beginPath();c.moveTo(L,yy);c.lineTo(w-R,yy);c.stroke();c.textAlign='right';c.fillStyle=chartColor('#43516a');c.fillText(compact(hi-(hi-lo)*i/3),L-8,yy+4)}c.beginPath();let prev=false;for(let i=0;i<24;i++){if(vals[i]==null){prev=false;continue}const xx=L+i/23*pw,yy=T+(hi-vals[i])/(hi-lo)*ph;if(prev)c.lineTo(xx,yy);else c.moveTo(xx,yy);prev=true}c.strokeStyle=chartColor('#b9650d');c.lineWidth=2.3;c.stroke();c.fillStyle=chartColor('#43516a');for(const i of [0,6,12,18,23]){c.textAlign=i===0?'left':i===23?'right':'center';c.fillText(String(i).padStart(2,'0')+':00',L+i/23*pw,h-8)}c.textAlign='left';c.fillText(unit('LMP'),L,10)}
