let definitionBubble,definitionAnchor,definitionHideTimer;
function definitionFor(text){const t=text.replace(/\s+/g,' ').trim();if(headingDefinitions[t])return headingDefinitions[t];if(conceptDefinitions[t])return conceptDefinitions[t];if(/^\d{4} projected peak$/.test(t))return 'The selected model’s saved annual coincident peak-demand projection for this year, in MW. It is not a subsequently verified actual observation.';if(/ MW$/.test(t)&&demandModels.some(m=>t.startsWith(m)))return conceptDefinitions[t.slice(0,-3)];return null}
function markDefinition(el,text,definition){if(!definition||el.querySelector('input[type=checkbox]'))return;el.classList.add('help-target');el.dataset.definition=definition;el.dataset.definitionTitle=text.trim();el.setAttribute('aria-describedby','conceptDefinition');el.setAttribute('aria-controls','conceptDefinition');el.setAttribute('aria-haspopup','dialog');if(el!==definitionAnchor)el.setAttribute('aria-expanded','false');if(el.tagName==='SPAN')el.setAttribute('role','button');if(!el.matches('button,a,input,select'))el.setAttribute('tabindex','0')}
function decorateDefinitions(){
 document.querySelectorAll('h1,h2,h3,th,.card .label,.card .value small,.section-label,.fact>span,.station-head .kicker,label,.project-objectives strong,.source-list>li>strong').forEach(el=>{const text=Array.from(el.childNodes).filter(n=>n.nodeType===3).map(n=>n.textContent).join(' ').trim()||el.textContent;let definition=definitionFor(text);if(!definition&&el.matches('h1,h2,h3'))definition='This section presents '+el.textContent.trim().replace(/\.$/,'')+'. Read the accompanying description for its scope and data source.';markDefinition(el,text,definition)});
 if($('tableNodeHeader'))markDefinition($('tableNodeHeader'),$('tableNodeHeader').textContent,definitionFor(labels[$('nodeMetric').value]));
 if($('tableRegionalHeader'))markDefinition($('tableRegionalHeader'),$('tableRegionalHeader').textContent,definitionFor(labels[$('regionalMetric').value]));
 const terms=Object.keys(conceptDefinitions).sort((a,b)=>b.length-a.length),escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),pattern=new RegExp('(?<![A-Za-z0-9_])('+terms.map(escape).join('|')+')(?![A-Za-z0-9_])','gi'),lookup=Object.fromEntries(terms.map(t=>[t.toLowerCase(),t]));
 document.querySelectorAll('p,.panel-sub,.card .foot,.notebook-note,.insight,.source-list li,.view-intro,.project-objectives span').forEach(root=>{if(root.closest('.help-target,#conceptDefinition'))return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('.help-target,button,a,select,option,script,style')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const text=n.textContent;pattern.lastIndex=0;const matches=[...text.matchAll(pattern)];if(!matches.length)continue;const fragment=document.createDocumentFragment();let end=0;for(const m of matches){fragment.append(document.createTextNode(text.slice(end,m.index)));const span=document.createElement('span');span.textContent=m[0];markDefinition(span,m[0],conceptDefinitions[lookup[m[0].toLowerCase()]]);fragment.append(span);end=m.index+m[0].length}fragment.append(document.createTextNode(text.slice(end)));n.replaceWith(fragment)}});
}
function hideDefinition(){if(definitionAnchor)definitionAnchor.setAttribute('aria-expanded','false');definitionBubble.hidden=true;definitionAnchor=null}
function showDefinition(target){hideDefinition();definitionAnchor=target;target.setAttribute('aria-expanded','true');definitionBubble.replaceChildren();const close=document.createElement('button');close.className='definition-close';close.type='button';close.setAttribute('aria-label','Close definition');close.textContent='×';close.onclick=hideDefinition;const title=document.createElement('strong');title.textContent=target.dataset.definitionTitle;const body=document.createElement('div');body.textContent=target.dataset.definition;definitionBubble.append(close,title,body);definitionBubble.hidden=false;const r=target.getBoundingClientRect(),b=definitionBubble.getBoundingClientRect(),vw=document.documentElement.clientWidth,vh=window.innerHeight;definitionBubble.style.left=Math.max(10,Math.min(r.left,vw-b.width-10))+'px';let top=r.bottom+8;if(top+b.height>vh-10)top=r.top-b.height-8;definitionBubble.style.top=Math.max(10,Math.min(top,vh-b.height-10))+'px'}
function toggleDefinition(target){if(definitionAnchor===target)hideDefinition();else showDefinition(target)}
function setupDefinitions(){
 definitionBubble=document.createElement('div');definitionBubble.id='conceptDefinition';definitionBubble.className='concept-definition';definitionBubble.setAttribute('role','dialog');definitionBubble.setAttribute('aria-label','Definition');definitionBubble.hidden=true;document.body.append(definitionBubble);
 document.addEventListener('click',e=>{if(e.target.closest('#conceptDefinition'))return;const target=e.target.closest('.help-target');if(target&&!e.target.closest('button,a,input,select')){if(target.tagName==='LABEL')e.preventDefault();toggleDefinition(target)}else hideDefinition()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideDefinition();return}const target=e.target.closest('.help-target');if(!e.repeat&&target&&(e.key==='Enter'||e.key===' ')&&!e.target.closest('button,a,input,select')){e.preventDefault();toggleDefinition(target)}});window.addEventListener('scroll',hideDefinition,true);window.addEventListener('resize',hideDefinition);
 decorateDefinitions();let timer;new MutationObserver(records=>{if(records.every(r=>r.target===definitionBubble||definitionBubble.contains(r.target)))return;clearTimeout(timer);timer=setTimeout(decorateDefinitions,80)}).observe(document.querySelector('.app'),{childList:true,characterData:true,subtree:true});
}

const SHIFT_DAY=86400000,SHIFT_STEP=300000;
function loadShiftScenario(rows,rangeStart,rangeEnd,loadKw,durationHours,fromMinute,toMinute){
 if(!Number.isFinite(loadKw)||loadKw<0||loadKw>100000)return {error:'Enter a load between 0 and 100,000 kW.'};
 if(!Number.isFinite(durationHours)||durationHours<.25||durationHours>12||Math.abs(durationHours*4-Math.round(durationHours*4))>1e-8)return {error:'Use a duration from 0.25 to 12 hours in 15-minute steps.'};
 if(!Number.isInteger(fromMinute)||!Number.isInteger(toMinute)||fromMinute<0||fromMinute>=1440||toMinute<0||toMinute>=1440)return {error:'Choose valid source and destination start times.'};
 const minutes=durationHours*60,nextDay=toMinute<=fromMinute,relativeTarget=toMinute+(nextDay?1440:0);
 if(relativeTarget<fromMinute+minutes)return {error:'The destination must start after the source window finishes.'};
 const priceIndex=D.nodeFields.indexOf('LMP')+1,prices=new Map(rows.map(r=>[r[0],r[priceIndex]])),steps=durationHours*12;
 function windowPrice(start){let sum=0;for(let i=1;i<=steps;i++){const p=prices.get(start+i*SHIFT_STEP);if(p==null||!Number.isFinite(p))return null;sum+=p/1000}return sum/steps}
 const pairs=[];let eligible=0,missing=0;
 for(let day=rangeStart;day<rangeEnd;day+=SHIFT_DAY){const from=day+fromMinute*60000,to=day+relativeTarget*60000;if(from+minutes*60000>rangeEnd||to+minutes*60000>rangeEnd)continue;eligible++;const source=windowPrice(from),destination=windowPrice(to);if(source===null||destination===null){missing++;continue}pairs.push({day,source,destination})}
 if(!pairs.length)return {error:'No complete paired windows in these dates. Expand the date range or choose different times.',eligible,missing};
 const sourcePrice=mean(pairs.map(r=>r.source)),targetPrice=mean(pairs.map(r=>r.destination)),energyKwh=loadKw*durationHours,sourceCost=energyKwh*sourcePrice,targetCost=energyKwh*targetPrice;
 return {sourcePrice,targetPrice,energyKwh,sourceCost,targetCost,saving:sourceCost-targetCost,pairs:pairs.length,eligible,missing,nextDay,steps};
}
function calculatorMarkup(){const times=Array.from({length:24},(_,h)=>'<option value="'+(h*60)+'">'+String(h).padStart(2,'0')+':00</option>').join('');return `<section class="panel load-shift" id="loadShift"><h2>Load-shift calculator</h2><p class="calculator-intro">Compare moving a flexible load to a later window using this node’s historical prices.</p><div class="calculator-line"><label for="shiftLoad">Load to shift</label><div class="calculator-number"><input id="shiftLoad" type="number" min="0" max="100000" step="any" value="500" inputmode="decimal"><span>kW</span></div></div><input id="shiftLoadSlider" type="range" min="0" max="2000" step="10" value="500" aria-label="Load to shift slider"><div class="calculator-line"><label for="shiftDuration">Duration</label><div class="calculator-number"><input id="shiftDuration" type="number" min="0.25" max="12" step="0.25" value="3"><span>h</span></div></div><input id="shiftDurationSlider" type="range" min="0.25" max="12" step="0.25" value="3" aria-label="Duration slider"><div class="calculator-times"><label for="shiftFrom">Move out of<select id="shiftFrom" aria-label="Move out of">${times}</select></label><label for="shiftTo">Move into<select id="shiftTo" aria-label="Move into">${times}</select></label></div><div id="shiftWindowNote" class="calculator-window-note"></div><div class="calculator-prices"><div><span>Source price</span><strong id="shiftSourcePrice">—</strong></div><div><span>Destination price</span><strong id="shiftTargetPrice">—</strong></div></div><div class="calculator-result" id="shiftResult"><span id="shiftResultLabel">Estimated reduction</span><strong id="shiftSaving">—</strong><small id="shiftEnergy"></small></div><div class="calculator-costs"><span>Before <b id="shiftBefore">—</b></span><span>After <b id="shiftAfter">—</b></span></div><div id="shiftEvidence" class="calculator-evidence" role="status" aria-live="polite"></div><p class="calculator-method">Historical scenario, not a price forecast. Energy-only spot exposure; retail tariffs, contracts, losses and other charges are excluded. Each pair needs all five-minute prices.</p></section>`}
function setupCalculator(){document.querySelector('#marketView .right').insertAdjacentHTML('afterbegin',calculatorMarkup());$('shiftFrom').value='1080';$('shiftTo').value='120';for(const [number,slider] of [['shiftLoad','shiftLoadSlider'],['shiftDuration','shiftDurationSlider']]){$(number).oninput=()=>{if(number==='shiftLoad'&&Number($(number).value)>2000&&Number($(number).value)<=100000)$(slider).max=String(Math.ceil(Number($(number).value)/500)*500);$(slider).value=$(number).value;renderCalculator()};$(slider).oninput=()=>{$(number).value=$(slider).value;renderCalculator()}}$('shiftFrom').onchange=renderCalculator;$('shiftTo').onchange=renderCalculator;}
function renderCalculator(){if(!$('shiftLoad')||!view.nodes)return;const load=Number($('shiftLoad').value),duration=Number($('shiftDuration').value),from=Number($('shiftFrom').value),to=Number($('shiftTo').value),result=(view.node!==$('node').value||Date.parse($('start').value+'T00:00:00+08:00')!==view.a||Date.parse($('end').value+'T00:00:00+08:00')+86400000!==view.b)?{error:'Choose a valid date range to calculate this scenario.'}:loadShiftScenario(view.nodes,view.a,view.b,load,duration,from,to),cash=x=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',minimumFractionDigits:2,maximumFractionDigits:2}).format(x),clock=m=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(Math.round(m%60)).padStart(2,'0');
 $('shiftWindowNote').textContent=clock(from)+'–'+clock(from+duration*60)+' → '+clock(to)+'–'+clock(to+duration*60)+(to<=from?' · destination next day':' · destination same day');
 if(result.error){for(const id of ['shiftSourcePrice','shiftTargetPrice','shiftSaving','shiftBefore','shiftAfter'])$(id).textContent='—';$('shiftResultLabel').textContent='Scenario unavailable';$('shiftEnergy').textContent='';$('shiftEvidence').textContent=result.error;$('shiftResult').classList.add('unavailable');return}
 $('shiftResult').classList.remove('unavailable');$('shiftResult').classList.toggle('increase',result.saving<0);$('shiftResultLabel').textContent=result.saving<0?'Estimated increase per shift':'Estimated reduction per shift';$('shiftSaving').textContent=cash(Math.abs(result.saving));$('shiftSourcePrice').textContent=cash(result.sourcePrice)+'/kWh';$('shiftTargetPrice').textContent=cash(result.targetPrice)+'/kWh';$('shiftBefore').textContent=cash(result.sourceCost);$('shiftAfter').textContent=cash(result.targetCost);$('shiftEnergy').textContent=num(load,0)+' kW × '+num(duration,2)+' h = '+num(result.energyKwh,0)+' kWh';$('shiftEvidence').textContent=view.node+' · '+result.pairs+' complete paired '+(result.pairs===1?'day':'days')+' in the selected dates'+(result.missing?' · '+result.missing+' incomplete '+(result.missing===1?'pair':'pairs')+' excluded':'')+'. Prices are paired-window arithmetic means.';
}

Object.assign(headingDefinitions,{
 'Panay':'Observed prices for candidate Panay buses, alongside Visayas-wide regional context.',
 'Market timeline':'Compare the selected bus quantity (left axis) with a Visayas regional quantity (right axis) over time.',
 'Load-shift calculator':'Estimate energy-only cost changes by moving a flexible load between complete historical price windows.',
 'Load to shift':'The flexible power moved between windows, in kW. The same load and duration are used before and after.',
 'Duration':'Hours of constant shifted load. For example, 500 kW for 3 hours equals 1,500 kWh.',
 'Move out of':'Start of the original load window, in Philippine time. Duration determines its end.',
 'Move into':'Start of the later load window. An earlier clock time means the following day. Windows cannot overlap.',
 'Regional context':'These background quantities cover the entire Visayas region; selected bus prices refer to Panay.',
 'Mean nodal price':'Arithmetic mean of available five-minute prices for the selected bus and dates; not energy-weighted.',
 'Matched interval coverage':'Percentage of expected five-minute intervals with both bus and regional records. It measures availability.'
});
Object.assign(conceptDefinitions,{
 'LMP':'Locational marginal price: the market price at an electrical node, including energy, losses and congestion. It is not a retail tariff.',
 'MAE':'Mean absolute error: the average size of prediction errors, in MW here. Smaller is better.',
 'RMSE':'Root mean squared error: an error measure in MW that gives greater weight to large mistakes.',
 'MAPE':'Mean absolute percentage error: average absolute error relative to actual demand. Undefined when actual demand is zero.',
 'CAGR':'Compound annual growth rate: the constant yearly rate connecting the 2024 actual peak to the selected projection.'
});



